 if(s.cafeEquipment&&Object.keys(cafeEquipment).some(k=>!Number.isInteger(s.cafeEquipment[k])||s.cafeEquipment[k]<0||s.cafeEquipment[k]>3))throw Error('Thiết bị cà phê không hợp lệ');
